from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        self.appointments = {}
        self.appointment_id = 0
        self.patient_appointments = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment in the past")

        if patient in self.patient_appointments and self.patient_appointments[patient]['end'] > now:
            raise ValueError("Patient already has an upcoming appointment")

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available at this time")

        self.appointment_id += 1
        self.appointments[self.appointment_id] = {'patient': patient, 'doctor': doctor, 'start': start, 'end': end, 'cancelled': False}
        self.patient_appointments[patient] = {'id': self.appointment_id, 'end': end}
        return self.appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self.appointments:
            raise ValueError("Appointment does not exist")

        appointment = self.appointments[appointment_id]
        if appointment['start'] - now < timedelta(hours=24):
            return  # Do not free the time slot if cancelled less than 24 hours before start

        appointment['cancelled'] = True
        self.patient_appointments[appointment['patient']] = {'id': appointment_id, 'end': now}

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for appointment in self.appointments.values():
            if appointment['doctor'] == doctor and not appointment['cancelled']:
                if (start < appointment['end'] and end > appointment['start']):
                    return False
        return True

# Example usage:
if __name__ == "__main__":
    scheduler = Scheduler()
    now = datetime.now()
    patient1 = "John"
    doctor1 = "Dr. Smith"
    start1 = now + timedelta(hours=1)
    end1 = now + timedelta(hours=2)

    appointment_id1 = scheduler.book(patient1, doctor1, start1, end1, now)
    print(f"Appointment {appointment_id1} booked for {patient1} with {doctor1} from {start1} to {end1}")

    try:
        scheduler.book(patient1, doctor1, start1 + timedelta(hours=3), end1 + timedelta(hours=3), now)
    except ValueError as e:
        print(e)

    try:
        scheduler.cancel(appointment_id1, now - timedelta(hours=1))
    except ValueError as e:
        print(e)

    scheduler.cancel(appointment_id1, now)
    print(f"Appointment {appointment_id1} cancelled")
```
This code implements the Scheduler class with the required methods. It uses a dictionary to store appointments and another dictionary to keep track of each patient's upcoming appointment. The `book` method checks for availability and patient's existing appointments, the `cancel` method checks for the time before the appointment and the `is_free` method checks for overlapping appointments. The example usage demonstrates how to use the Scheduler class.

